11: 	"github.com/spf13/cobra"
12: )
13: 
14: func NewGetCmd(cfg *clicfg.Config) *cobra.Command {
15: 	var (
16: 		organizationId string
17: 		projectId      string
18: 	)
19: 
20: 	const (
21: 		organizationIdFlag = "organization-id"
22: 		projectIdFlag      = "project-id"
23: 	)
24: 
25: 	cmd := &cobra.Command{
26: 		Use:   "get <id>",
27: 		Short: "Returns deployment details",
28: 		Long:  "Returns details about a specific Fleet Manager deployment.",
29: 		Args:  cobra.ExactArgs(1),
30: 		PreRunE: func(cmd *cobra.Command, args []string) error {
31: 			return resolveFlags(cmd, cfg, organizationIdFlag, projectIdFlag, &organizationId, &projectId)
32: 		},
33: 		RunE: func(cmd *cobra.Command, args []string) error {
34: 			deploymentId := args[0]
35: 			path := fmt.Sprintf("/organizations/%s/projects/%s/fleet-manager/deployments/%s", organizationId, projectId, deploymentId)
36: 
37: 			cmd.SilenceUsage = true
38: 			resBody, statusCode, err := api.MakeRequest(cfg, path, &api.RequestConfig{
39: 				Method:  http.MethodGet,
40: 				Version: api.AuraApiVersion2,
41: 			})
42: 			if err != nil {
43: 				return err
44: 			}
45: 
46: 			if api.IsSuccessful(statusCode) {
47: 				fields := []string{
48: 					"id",
49: 					"name",
50: 					"dbms:edition",
51: 					"dbms:packaging",
52: 					"token:expiry_time",
53: 					"token:auto_rotated",
54: 					"token:creation_time",
55: 				}
56: 				output.PrintBody(cmd, cfg, resBody, fields)
57: 			}
58: 
59: 			return nil
60: 		},
61: 	}
62: 	cmd.Flags().StringVar(&organizationId, organizationIdFlag, "", "(required) Organization ID")
63: 	cmd.Flags().StringVar(&projectId, projectIdFlag, "", "(required) Project/tenant ID")
64: 
65: 	return cmd
66: }
67: 
68: func resolveFlags(cmd *cobra.Command, cfg *clicfg.Config, orgIdFlag, projIdFlag string, orgId, projId *string) error {
69: 	defaultSetting, err := cfg.Settings.Aura.GetDefault()
70: 	if err != nil {
71: 		return err
72: 	}
73: 	if *orgId == "" {
74: 		if defaultSetting.OrganizationId == "" {
75: 			if err := cmd.MarkFlagRequired(orgIdFlag); err != nil {
76: 				return err
77: 			}
78: 		} else {
79: 			*orgId = defaultSetting.OrganizationId
80: 		}
81: 	}
82: 
83: 	if *projId == "" {
84: 		if defaultSetting.ProjectId == "" {
85: 			if err := cmd.MarkFlagRequired(projIdFlag); err != nil {
86: 				return err
87: 			}
88: 		} else {
89: 			*projId = defaultSetting.ProjectId
90: 		}
91: 	}
92: 
93: 	return nil
94: }
